Please debug the following Typescript code.

### Problem Description
Fix runWithConcurrency to execute promises limiting concurrent tasks to maxConcurrent.

### Buggy Code
```typescript
export async function runWithConcurrency<T>(
  tasks: (() => Promise<T>)[],
  maxConcurrent: number
): Promise<T[]> {
  return Promise.all(tasks.map(t => t()));
}
```

Identify the bug, provide the corrected implementation, and supply a verified unit test suite.

### Analysis & Root Cause
Spawn a bounded pool of asynchronous workers that pull task indices atomically from a shared cursor.

### Corrected Implementation
```typescript
export async function runWithConcurrency<T>(
  tasks: (() => Promise<T>)[],
  maxConcurrent: number
): Promise<T[]> {
  const results: T[] = new Array(tasks.length);
  let nextIdx = 0;

  async function worker() {
    while (nextIdx < tasks.length) {
      const cur = nextIdx++;
      results[cur] = await tasks[cur]();
    }
  }

  const workers = Array.from({ length: Math.min(maxConcurrent, tasks.length) }, () => worker());
  await Promise.all(workers);
  return results;
}
```

### Unit Test Suite
```typescript
import { describe, it } from 'node:test';
import assert from 'node:assert';
import { runWithConcurrency } from './solution.ts';

describe('runWithConcurrency', () => {
  it('respects concurrency limit', async () => {
    let active = 0;
    let maxSeen = 0;
    const makeTask = (val: number) => async () => {
      active++;
      maxSeen = Math.max(maxSeen, active);
      await new Promise(r => setTimeout(r, 10));
      active--;
      return val * 2;
    };
    const tasks = [1, 2, 3, 4, 5].map(makeTask);
    const res = await runWithConcurrency(tasks, 2);
    assert.deepStrictEqual(res, [2, 4, 6, 8, 10]);
    assert.strictEqual(maxSeen <= 2, true);
  });
});
```

Please debug the following Typescript code.

### Problem Description
Fix TS LRUCache to utilize Map key iteration for O(1) eviction.

### Buggy Code
```typescript
export class LRUCache<K, V> {
  private map = new Map<K, V>();
  private capacity: number;
  constructor(capacity: number) {
    this.capacity = capacity;
  }
  get(key: K): V | undefined {
    return this.map.get(key);
  }
  set(key: K, val: V): void {
    this.map.set(key, val);
  }
}
```

Identify the bug, provide the corrected implementation, and supply a verified unit test suite.

### Analysis & Root Cause
Re-insert key on read and evict the first Map key when capacity limit is reached.

### Corrected Implementation
```typescript
export class LRUCache<K, V> {
  private map = new Map<K, V>();
  private capacity: number;
  constructor(capacity: number) {
    this.capacity = capacity;
  }
  get(key: K): V | undefined {
    if (!this.map.has(key)) return undefined;
    const val = this.map.get(key)!;
    this.map.delete(key);
    this.map.set(key, val);
    return val;
  }
  set(key: K, val: V): void {
    if (this.map.has(key)) {
      this.map.delete(key);
    } else if (this.map.size >= this.capacity) {
      const oldestKey = this.map.keys().next().value;
      if (oldestKey !== undefined) this.map.delete(oldestKey);
    }
    this.map.set(key, val);
  }
}
```

### Unit Test Suite
```typescript
import { describe, it } from 'node:test';
import assert from 'node:assert';
import { LRUCache } from './solution.ts';

describe('LRUCache TS', () => {
  it('maintains recency', () => {
    const c = new LRUCache<string, number>(2);
    c.set('a', 1);
    c.set('b', 2);
    assert.strictEqual(c.get('a'), 1);
    c.set('c', 3);
    assert.strictEqual(c.get('b'), undefined);
    assert.strictEqual(c.get('a'), 1);
    assert.strictEqual(c.get('c'), 3);
  });
});
```

