### Problem Description
Fix CircularQueue so enqueue correctly wraps around buffer when tail reaches capacity.

### Buggy Code
```typescript
export class CircularQueue<T> {
  private buffer: (T | undefined)[];
  private head = 0;
  private tail = 0;
  private count = 0;
  private capacity: number;
  constructor(capacity: number) {
    this.capacity = capacity;
    this.buffer = new Array(capacity);
  }
  enqueue(item: T): boolean {
    if (this.isFull()) return false;
    this.buffer[this.tail] = item;
    this.tail++;
    this.count++;
    return true;
  }
  dequeue(): T | undefined {
    if (this.isEmpty()) return undefined;
    const item = this.buffer[this.head];
    this.buffer[this.head] = undefined;
    this.head = (this.head + 1) % this.capacity;
    this.count--;
    return item;
  }
  isFull(): boolean { return this.count === this.capacity; }
  isEmpty(): boolean { return this.count === 0; }
}
```

Identify the bug, provide the corrected implementation, and supply a verified unit test suite.

### Analysis & Root Cause
Apply (this.tail + 1) % this.capacity when incrementing tail index.

### Corrected Implementation
```typescript
export class CircularQueue<T> {
  private buffer: (T | undefined)[];
  private head = 0;
  private tail = 0;
  private count = 0;
  private capacity: number;
  constructor(capacity: number) {
    this.capacity = capacity;
    this.buffer = new Array(capacity);
  }
  enqueue(item: T): boolean {
    if (this.isFull()) return false;
    this.buffer[this.tail] = item;
    this.tail = (this.tail + 1) % this.capacity;
    this.count++;
    return true;
  }
  dequeue(): T | undefined {
    if (this.isEmpty()) return undefined;
    const item = this.buffer[this.head];
    this.buffer[this.head] = undefined;
    this.head = (this.head + 1) % this.capacity;
    this.count--;
    return item;
  }
  isFull(): boolean { return this.count === this.capacity; }
  isEmpty(): boolean { return this.count === 0; }
}
```

### Unit Test Suite
```typescript
import { describe, it } from 'node:test';
import assert from 'node:assert';
import { CircularQueue } from './solution.ts';

describe('CircularQueue', () => {
  it('wraps around and dequeues properly', () => {
    const q = new CircularQueue<number>(2);
    assert.strictEqual(q.enqueue(1), true);
    assert.strictEqual(q.enqueue(2), true);
    assert.strictEqual(q.enqueue(3), false);
    assert.strictEqual(q.dequeue(), 1);
    assert.strictEqual(q.enqueue(3), true);
    assert.strictEqual(q.dequeue(), 2);
    assert.strictEqual(q.dequeue(), 3);
